def normalize_units(data: list, unit_map: dict) -> list:
    for row in data:
        for i, cell in enumerate(row):
            for unit, norm_unit in unit_map.items():
                if unit in cell:
                    row[i] = cell.replace(unit, norm_unit)
    return data
